  private static final Logger log = LoggerFactory.getLogger(OtelEnvironmentConfigSource.class);

  /** The maximum number of custom OpenTelemetry resource attributes mapped to Datadog tags. */
  private static final int MAX_OTEL_RESOURCE_ATTRIBUTES = 10;

  /** The Datadog OpenTelemetry compatibility flag as a system property. */
  private static final String OTEL_ENABLED_PROPERTY = "dd.trace.otel.enabled";
  /** The Datadog OpenTelemetry compatibility flag as an environment variable. */
  private static final String OTEL_ENABLED_ENV_VAR = "DD_TRACE_OTEL_ENABLED";

  /** The properties to read the configuration from, or {@code null} to read from the environment. */
  private final Properties properties;
  /** The translated Datadog configuration, indexed by Datadog configuration key. */
  private final Map<String, String> configuration;

  public OtelEnvironmentConfigSource() {
    this(null);
  }

  public OtelEnvironmentConfigSource(Properties properties) {
    this.properties = properties;
    this.configuration = new HashMap<>();
    if (isOtelIntegrationEnabled()) {
      loadConfiguration();
    }
  }

  @Override
  protected String get(String key) {
    return this.configuration.get(key);
  }

  @Override
  public ConfigOrigin origin() {
    return ConfigOrigin.ENV;
  }

  /**
   * Checks whether the OpenTelemetry compatibility mode is enabled.
   *
   * @return {@code true} if the OpenTelemetry translation should be applied, {@code false}
   *     otherwise.
   */
  private boolean isOtelIntegrationEnabled() {
    return Boolean.parseBoolean(getProperty(OTEL_ENABLED_PROPERTY, OTEL_ENABLED_ENV_VAR));
  }

